sp_widget.css:
.skillsync-role-header {
  margin-bottom: 18px;
  padding: 16px;
  border: 1px solid #c8d8de;
  border-radius: 6px;
  background: #f4f8fa;
}
.skillsync-role-header h2 {
  margin: 0 0 6px;
  color: #114b5f;
  font-size: 20px;
}
.skillsync-role-header ul {
  margin: 8px 0 0;
  padding-left: 18px;
}

sp_widget.script:
(function() {
  data.role = 'Authenticated User';
  data.greeting = 'Hello, Authenticated User.';
  data.links = [];

  if (!gs.isLoggedIn()) {
    data.role = 'Guest';
    data.greeting = 'Hello, Guest.';
    return;
  }

  var roleLabels = [
    { role: 'x_2311790_skills_0.admin', label: 'SkillSync Administrator' },
    { role: 'admin', label: 'Administrator' },
    { role: 'x_2311790_skills_0.recruiter', label: 'Recruiter' },
    { role: 'x_2311790_skills_0.org_head', label: 'Org Head' },
    { role: 'x_2311790_skills_0.student', label: 'Student' },
    { role: 'x_2311790_skills_0.student_profile_user', label: 'Student Profile User' },
    { role: 'x_2311790_skills_0.student_skill_user', label: 'Student Skill User' },
    { role: 'x_2311790_skills_0.skill_master_user', label: 'Skill Master User' },
    { role: 'x_2311790_skills_0.internship_user', label: 'Internship User' },
    { role: 'x_2311790_skills_0.internship_application_user', label: 'Applicant' }
  ];

  for (var i = 0; i < roleLabels.length; i++) {
    if (gs.hasRole(roleLabels[i].role)) {
      data.role = roleLabels[i].label;
      break;
    }
  }

  data.greeting = 'Hello, ' + data.role + '.';

  if (gs.hasRole('x_2311790_skills_0.recruiter') || gs.hasRole('x_2311790_skills_0.admin') || gs.hasRole('admin'))
    data.links.push({ href: '/recruiter_review', label: 'Recruiter Review' });
  if (gs.hasRole('x_2311790_skills_0.student') || gs.hasRole('x_2311790_skills_0.student_profile_user'))
    data.links.push({ href: '/resume_upload', label: 'Upload Resume' });
  if (gs.hasRole('x_2311790_skills_0.org_head') || gs.hasRole('x_2311790_skills_0.internship_user'))
    data.links.push({ href: '/internships', label: 'Internships' });
})();
